  ?s a brick:Serves .
  ?s brick:object ?o .
  ?s a ?cls .
} LIMIT 20

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(str(?s) || str(?o) || str(?p) LIKE "%AHU03%")
} LIMIT 100

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s WHERE {
  ?s a ref:IFCReference .
  ?s ?p "AHU03" .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?zone ?sensor ?sensorTs ?tsid WHERE {
  ?vav rdf:type/[] <https://brickschema.org/schema/Brick#VAV> .
}
LIMIT 5

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?zone ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?sensor brick:isLocationOf ?zone .
  ?sensor ref:hasExternalReference ?ext .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?p ?o WHERE {
  ?sensor ?p ?o .
  FILTER(str(?sensor) CONTAINS "Zone_Air_Temperature_Sensor")
}

